import java.nio.charset.StandardCharsets;

public final class Decoder {

    private Decoder() {
    }

    /** Returns the text the UTF-8 bytes encode. */
    public static String decode(byte[] utf8) {
        return new String(utf8, StandardCharsets.UTF_8);
    }
}

